mapper.select:
SELECT c.id AS id, c.student_name AS studentName, c.consult_date AS consultDate, c.school AS school, c.phone AS phone, c.content AS content, c.grade_key AS gradeKey, gc.grade_name AS gradeName, i.inflow_route_name AS inflowRouteName, c.inflow_route_key AS inflowRouteKey, c.progress_key AS progressKey, c.consult_type AS type, c.consult_key AS consultKey, u.user_name AS userName, ps.invite_sent_at AS send_at, ps.registered_at AS registered_at, c.inquiry_hoho AS inquiryHoho, c.inquiry_han AS inquiryHan, c.inquiry_book AS inquiryBook, c.inquiry_doc AS inquiryDoc, c.end_reason AS endReason, c.ended_at AS endedAt, u2.user_name AS endUserName FROM ERP_CONSULT c JOIN erp_user u ON c.user_code = u.user_code JOIN erp_grade_code gc ON c.grade_key = gc.grade_key LEFT JOIN erp_inflow_route i ON c.inflow_route_key = i.inflow_route_key JOIN erp_progress_code pc ON c.progress_key = pc.progress_key LEFT JOIN erp_pending_student ps ON ps.send_key = c.send_key LEFT JOIN erp_user u2 ON c.end_user_code = u2.user_code WHERE c.center_code = #{centerCode} AND c.consult_date BETWEEN #{startDate} AND #{endDate}
AND c.progress_key = #{progress}
AND ( c.student_name LIKE CONCAT('%', #{keyword}, '%') OR c.phone LIKE CONCAT('%', #{keyword}, '%') OR c.school LIKE CONCAT('%', #{keyword}, '%') OR gc.grade_name LIKE CONCAT('%', #{keyword}, '%') OR u.user_name = #{keyword} )
AND c.user_code = #{userCode}
ORDER BY
CASE WHEN (CAST(c.inquiry_han AS INT) + CAST(c.inquiry_book AS INT) + CAST(c.inquiry_hoho AS INT)) >= 2 THEN 1 ELSE 0 END DESC, CASE WHEN c.inquiry_han = 1 THEN 3 WHEN c.inquiry_book = 1 THEN 2 WHEN c.inquiry_hoho = 1 THEN 1 ELSE 0 END DESC, c.consult_date DESC
CASE WHEN (CAST(c.inquiry_han AS INT) + CAST(c.inquiry_book AS INT) + CAST(c.inquiry_hoho AS INT)) >= 2 THEN 1 ELSE 0 END DESC, CASE WHEN c.inquiry_book = 1 THEN 3 WHEN c.inquiry_hoho = 1 THEN 2 WHEN c.inquiry_han = 1 THEN 1 ELSE 0 END DESC, c.consult_date DESC
CASE WHEN c.inquiry_hoho = 1 THEN 3 WHEN c.inquiry_han = 1 THEN 2 WHEN c.inquiry_book = 1 THEN 1 ELSE 0 END DESC, c.consult_date DESC
c.student_name ASC c.consult_date ASC gc.grade_name ASC u.user_name ASC c.progress_key ASC c.consult_date ASC
c.student_name DESC c.consult_date DESC gc.grade_name DESC u.user_name DESC c.progress_key DESC c.consult_date DESC

WITH ranked AS ( SELECT c.id, c.student_name, c.phone, c.school, c.grade_key, gc.grade_name, c.inflow_route_key, c.consult_type AS type, c.content, c.consult_date, c.progress_key, COUNT(*) OVER (PARTITION BY c.phone) AS consultCount, ROW_NUMBER() OVER (PARTITION BY c.phone ORDER BY c.consult_date DESC) AS rn FROM ERP_CONSULT c JOIN erp_grade_code gc ON c.grade_key = gc.grade_key WHERE c.center_code = #{centerCode}
AND ( c.student_name LIKE CONCAT('%', #{keyword}, '%') OR c.phone LIKE CONCAT('%', #{keyword}, '%') )
) SELECT id, student_name AS studentName, phone, school, grade_key AS gradeKey, grade_name AS gradeName, inflow_route_key AS inflowRouteKey, type, content, CONVERT(NVARCHAR(10), consult_date, 120) AS lastConsultDate, consultCount FROM ranked WHERE rn = 1 ORDER BY consult_date DESC

SELECT c.id AS id, c.student_name AS studentName, c.consult_date AS consultDate, c.school AS school, c.phone AS phone, c.content AS content, c.grade_key AS gradeKey, g.grade_name AS gradeName, i.inflow_route_name AS inflowRouteName, c.progress_key AS progressKey, u.user_name AS userName, c.consult_type AS type, eps.registered_at AS registerDate FROM ERP_CONSULT c JOIN erp_grade_code g ON c.grade_key = g.grade_key LEFT JOIN erp_inflow_route i ON c.inflow_route_key = i.inflow_route_key LEFT JOIN erp_user u ON c.user_code = u.user_code LEFT JOIN erp_pending_student eps ON eps.send_key = c.send_key WHERE c.center_code = #{centerCode} AND c.phone IN ( SELECT DISTINCT phone FROM ERP_CONSULT WHERE center_code = #{centerCode} AND user_code = #{userCode}
AND consult_date BETWEEN #{startDate} AND #{endDate}
)
AND c.consult_date BETWEEN #{startDate} AND #{endDate}
ORDER BY c.consult_date DESC

